**Plan**
- A `ShopItem` ScriptableObject stores the name and price, and a `CurrencyManager` component holds the coin balance with an `OnChanged` event.
- `ShopSystem.TryBuy(item)` checks the balance, deducts the price through the currency manager and raises `OnPurchased`.
- A UI Toolkit list shows one Buy button per item and a coin label that updates from the event.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UIElements;

// Tip: move ShopItem into its own ShopItem.cs file to create assets from Assets > Create > Shop > Item.
[CreateAssetMenu(menuName = "Shop/Item")]
public class ShopItem : ScriptableObject
{
    public string displayName = "Item";
    public int price = 10;
}

public class CurrencyManager : MonoBehaviour
{
    [SerializeField] private int coins = 100;

    public event Action<int> OnChanged;
    public int Coins { get { return coins; } }

    public bool TrySpend(int amount)
    {
        if (amount < 0 || coins < amount) return false;
        coins -= amount;
        if (OnChanged != null) OnChanged(coins);
        return true;
    }

    public void Add(int amount)
    {
        if (amount <= 0) return;
        coins += amount;
        if (OnChanged != null) OnChanged(coins);
    }
}

public class ShopSystem : MonoBehaviour
{
    [SerializeField] private CurrencyManager currency;
    [SerializeField] private List<ShopItem> items = new List<ShopItem>();

    public event Action<ShopItem> OnPurchased;
    private Label coinLabel;
    private Label messageLabel;

    private void OnEnable()
    {
        if (currency == null) currency = FindObjectOfType<CurrencyManager>();

        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.style.alignItems = Align.Center;
        root.style.paddingTop = 60;

        coinLabel = new Label();
        coinLabel.style.fontSize = 40;
        coinLabel.style.color = new Color(1f, 0.85f, 0.3f, 1f);
        root.Add(coinLabel);

        foreach (ShopItem item in items)
        {
            ShopItem captured = item;
            Button buy = new Button(() => TryBuy(captured));
            buy.text = item.displayName + " - " + item.price + " coins";
            buy.style.width = 420;
            buy.style.height = 56;
            buy.style.fontSize = 24;
            buy.style.marginTop = 8;
            root.Add(buy);
        }

        messageLabel = new Label();
        messageLabel.style.fontSize = 24;
        messageLabel.style.color = Color.white;
        messageLabel.style.marginTop = 16;
        root.Add(messageLabel);

        currency.OnChanged += UpdateCoins;
        UpdateCoins(currency.Coins);
    }

    private void OnDisable()
    {
        if (currency != null) currency.OnChanged -= UpdateCoins;
    }

    private void UpdateCoins(int value)
    {
        coinLabel.text = "Coins: " + value;
    }

    public bool TryBuy(ShopItem item)
    {
        if (item == null || !currency.TrySpend(item.price))
        {
            messageLabel.text = "Not enough coins!";
            return false;
        }
        messageLabel.text = "Bought " + item.displayName;
        if (OnPurchased != null) OnPurchased(item);
        return true;
    }
}
```

Prices live in ShopItem assets, and the shop never edits the balance directly: it asks `CurrencyManager.TrySpend`, which refuses if the player cannot afford it. The coin label subscribes to `OnChanged`, so it updates for any source of income or spending, and `OnPurchased` lets an inventory script hand over the item.

**Plan**
- A singleton `CurrencyManager` (lazy `Instance`, `DontDestroyOnLoad`) holds the balance.
- `Add(amount)` and `TrySpend(amount)` validate input, update the balance and raise `OnChanged(newBalance)`.
- The balance is loaded from PlayerPrefs on creation and saved after every change.

```csharp
using System;
using UnityEngine;

public class CurrencyManager : MonoBehaviour
{
    private const string SaveKey = "Currency.Coins";

    private static CurrencyManager instance;
    private static bool quitting;

    public static CurrencyManager Instance
    {
        get
        {
            if (instance == null && !quitting)
            {
                instance = FindObjectOfType<CurrencyManager>();
                if (instance == null)
                {
                    GameObject go = new GameObject("CurrencyManager");
                    instance = go.AddComponent<CurrencyManager>();
                }
            }
            return instance;
        }
    }

    [SerializeField] private int startingCoins = 0;

    private int balance;
    private bool loaded;

    public event Action<int> OnChanged;
    public int Balance
    {
        get
        {
            EnsureLoaded();
            return balance;
        }
    }

    private void Awake()
    {
        if (instance != null && instance != this)
        {
            Destroy(gameObject);
            return;
        }
        instance = this;
        DontDestroyOnLoad(gameObject);
        EnsureLoaded();
    }

    private void OnApplicationQuit()
    {
        quitting = true;
        Save();
    }

    private void EnsureLoaded()
    {
        if (loaded) return;
        balance = PlayerPrefs.GetInt(SaveKey, startingCoins);
        loaded = true;
    }

    public void Add(int amount)
    {
        if (amount <= 0) return;
        EnsureLoaded();
        long total = (long)balance + amount;
        balance = (int)Math.Min(total, int.MaxValue);
        Changed();
    }

    public bool TrySpend(int amount)
    {
        EnsureLoaded();
        if (amount < 0 || balance < amount) return false;
        balance -= amount;
        Changed();
        return true;
    }

    public bool CanAfford(int amount)
    {
        EnsureLoaded();
        return amount >= 0 && balance >= amount;
    }

    private void Changed()
    {
        Save();
        if (OnChanged != null) OnChanged(balance);
    }

    private void Save()
    {
        PlayerPrefs.SetInt(SaveKey, balance);
        PlayerPrefs.Save();
    }
}
```

Any script can call `CurrencyManager.Instance.Add(10)` or `TrySpend(25)`; the instance is created on first use and survives scene loads. Adds saturate at `int.MaxValue` instead of overflowing, spending below zero is refused, and every change is written to PlayerPrefs before `OnChanged` fires, so UI and saves never disagree.

**Plan**
- A list of `UpgradeData` entries (name, base cost, current level) with cost computed as `baseCost * 2^level`.
- A UI Toolkit shop builds one row per upgrade with a label and a Buy button, and a wallet label shows the coins.
- After every purchase or coin change, all buttons are refreshed and disabled when the player cannot afford the next level.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UIElements;

[Serializable]
public class UpgradeData
{
    public string upgradeName = "Upgrade";
    public int baseCost = 10;
    public int level;
    public int maxLevel = 10;

    public int NextCost { get { return baseCost * (1 << level); } }
    public bool IsMaxed { get { return level >= maxLevel; } }
}

public class UpgradeShopUI : MonoBehaviour
{
    [SerializeField] private int coins = 100;
    [SerializeField] private List<UpgradeData> upgrades = new List<UpgradeData>
    {
        new UpgradeData { upgradeName = "Damage", baseCost = 10 },
        new UpgradeData { upgradeName = "Speed", baseCost = 15 },
        new UpgradeData { upgradeName = "Health", baseCost = 20 },
    };

    private readonly List<Button> buttons = new List<Button>();
    private Label walletLabel;

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.style.alignItems = Align.Center;
        root.style.paddingTop = 60;

        walletLabel = new Label();
        walletLabel.style.fontSize = 40;
        walletLabel.style.color = new Color(1f, 0.85f, 0.3f, 1f);
        walletLabel.style.marginBottom = 20;
        root.Add(walletLabel);

        buttons.Clear();
        for (int i = 0; i < upgrades.Count; i++)
        {
            int index = i;
            Button button = new Button(() => Buy(index));
            button.style.width = 520;
            button.style.height = 64;
            button.style.fontSize = 26;
            button.style.marginBottom = 10;
            root.Add(button);
            buttons.Add(button);
        }
        Refresh();
    }

    public void AddCoins(int amount)
    {
        coins += amount;
        Refresh();
    }

    private void Buy(int index)
    {
        UpgradeData upgrade = upgrades[index];
        if (upgrade.IsMaxed || coins < upgrade.NextCost) return;
        coins -= upgrade.NextCost;
        upgrade.level++;
        Refresh();
    }

    private void Refresh()
    {
        walletLabel.text = "Coins: " + coins;
        for (int i = 0; i < upgrades.Count; i++)
        {
            UpgradeData upgrade = upgrades[i];
            bool affordable = !upgrade.IsMaxed && coins >= upgrade.NextCost;
            buttons[i].text = upgrade.IsMaxed
                ? upgrade.upgradeName + "  Lv " + upgrade.level + " (MAX)"
                : upgrade.upgradeName + "  Lv " + upgrade.level + "  -  cost " + upgrade.NextCost;
            buttons[i].SetEnabled(affordable);
            buttons[i].style.opacity = affordable ? 1f : 0.45f;
        }
    }

    private void Update()
    {
        if (Input.GetKeyDown(KeyCode.Space)) AddCoins(25);
    }
}
```

The cost of the next level is `baseCost` shifted left by the current level, which doubles it each time (10, 20, 40, 80...). Every purchase or income event calls `Refresh`, which rewrites each button's text and disables it when the next level is unaffordable or maxed. Space adds 25 coins for testing.

**Plan**
- Generators have an owned count, a base income per second and a cost that grows by 15% per owned unit.
- Each frame the game adds `income * deltaTime` to a money value, and a UI Toolkit panel shows money, income per second and a Buy button per generator.
- On quit the current UTC time is saved with the money (as ticks in a string); on load the elapsed seconds, capped at 8 hours, are multiplied by the income and added as offline earnings.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UIElements;

[Serializable]
public class Generator
{
    public string generatorName = "Lemonade Stand";
    public double baseCost = 10;
    public double incomePerSecond = 1;
    public int owned;

    public double NextCost { get { return baseCost * Math.Pow(1.15, owned); } }
    public double Income { get { return incomePerSecond * owned; } }
}

public class IdleIncomeSystem : MonoBehaviour
{
    private const string MoneyKey = "Idle.Money";
    private const string TimeKey = "Idle.LastTicks";
    private const string OwnedKey = "Idle.Owned.";
    private const double MaxOfflineSeconds = 8 * 3600;

    [SerializeField] private List<Generator> generators = new List<Generator>
    {
        new Generator { generatorName = "Lemonade Stand", baseCost = 10, incomePerSecond = 1 },
        new Generator { generatorName = "Bakery", baseCost = 120, incomePerSecond = 8 },
        new Generator { generatorName = "Factory", baseCost = 1500, incomePerSecond = 60 },
    };

    private double money;
    private Label moneyLabel;
    private Label offlineLabel;
    private readonly List<Button> buttons = new List<Button>();

    private double TotalIncome
    {
        get
        {
            double total = 0;
            foreach (Generator g in generators) total += g.Income;
            return total;
        }
    }

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.style.alignItems = Align.Center;
        root.style.paddingTop = 50;

        moneyLabel = new Label();
        moneyLabel.style.fontSize = 44;
        moneyLabel.style.color = new Color(0.5f, 1f, 0.5f, 1f);
        root.Add(moneyLabel);

        offlineLabel = new Label();
        offlineLabel.style.fontSize = 24;
        offlineLabel.style.color = new Color(1f, 0.85f, 0.3f, 1f);
        offlineLabel.style.marginBottom = 16;
        root.Add(offlineLabel);

        buttons.Clear();
        for (int i = 0; i < generators.Count; i++)
        {
            int index = i;
            Button button = new Button(() => Buy(index));
            button.style.width = 560;
            button.style.height = 60;
            button.style.fontSize = 24;
            button.style.marginBottom = 8;
            root.Add(button);
            buttons.Add(button);
        }

        Load();
    }

    private void Load()
    {
        money = double.Parse(PlayerPrefs.GetString(MoneyKey, "0"), System.Globalization.CultureInfo.InvariantCulture);
        for (int i = 0; i < generators.Count; i++) generators[i].owned = PlayerPrefs.GetInt(OwnedKey + i, generators[i].owned);

        string ticksText = PlayerPrefs.GetString(TimeKey, "");
        long ticks;
        if (long.TryParse(ticksText, out ticks))
        {
            double away = (DateTime.UtcNow - new DateTime(ticks, DateTimeKind.Utc)).TotalSeconds;
            away = Math.Max(0, Math.Min(away, MaxOfflineSeconds));
            double earned = away * TotalIncome;
            money += earned;
            if (earned > 0) offlineLabel.text = "Welcome back! Offline earnings: " + earned.ToString("N0");
        }
    }

    private void Save()
    {
        PlayerPrefs.SetString(MoneyKey, money.ToString(System.Globalization.CultureInfo.InvariantCulture));
        PlayerPrefs.SetString(TimeKey, DateTime.UtcNow.Ticks.ToString());
        for (int i = 0; i < generators.Count; i++) PlayerPrefs.SetInt(OwnedKey + i, generators[i].owned);
        PlayerPrefs.Save();
    }

    private void Buy(int index)
    {
        Generator g = generators[index];
        if (money < g.NextCost) return;
        money -= g.NextCost;
        g.owned++;
        Save();
    }

    private void Update()
    {
        money += TotalIncome * Time.deltaTime;
        moneyLabel.text = "$" + money.ToString("N0") + "   (+" + TotalIncome.ToString("N1") + "/s)";
        for (int i = 0; i < generators.Count; i++)
        {
            Generator g = generators[i];
            buttons[i].text = g.generatorName + " x" + g.owned + "  -  buy for $" + g.NextCost.ToString("N0");
            buttons[i].SetEnabled(money >= g.NextCost);
        }
    }

    private void OnApplicationPause(bool paused) { if (paused) Save(); }
    private void OnApplicationQuit() { Save(); }
}
```

Income is simply owned count times income per second, added every frame. When the game starts it reads the UTC tick count saved at the last quit, clamps the elapsed time to eight hours, and credits that many seconds of the current income as offline earnings, shown in a label. Generator prices rise by 15% per owned unit, and the game also saves when the app is paused (mobile).

**Plan**
- A loot table is a list of rewards with a name and a weight; `Roll` picks one using a random number across the total weight.
- A UI Toolkit panel shows an Open button and a result label; the result is coloured by how rare it is.
- A running tally of how often each reward dropped is displayed under the result to make the odds visible.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UIElements;

[Serializable]
public class LootReward
{
    public string rewardName = "Coins";
    [Min(0f)] public float weight = 10f;
    public Color color = Color.white;
}

public class LootBoxUI : MonoBehaviour
{
    [SerializeField] private List<LootReward> table = new List<LootReward>
    {
        new LootReward { rewardName = "50 Coins", weight = 60f, color = new Color(0.8f, 0.8f, 0.8f) },
        new LootReward { rewardName = "Health Potion", weight = 25f, color = new Color(0.4f, 0.9f, 0.5f) },
        new LootReward { rewardName = "Rare Sword", weight = 12f, color = new Color(0.4f, 0.6f, 1f) },
        new LootReward { rewardName = "LEGENDARY CROWN", weight = 3f, color = new Color(1f, 0.7f, 0.15f) },
    };

    private readonly Dictionary<string, int> history = new Dictionary<string, int>();
    private Label resultLabel;
    private Label historyLabel;

    public event Action<LootReward> OnOpened;

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.style.alignItems = Align.Center;
        root.style.justifyContent = Justify.Center;

        Button open = new Button(Open);
        open.text = "Open Loot Box";
        open.style.width = 420;
        open.style.height = 80;
        open.style.fontSize = 32;
        root.Add(open);

        resultLabel = new Label("Click to open!");
        resultLabel.style.fontSize = 54;
        resultLabel.style.marginTop = 30;
        resultLabel.style.color = Color.white;
        root.Add(resultLabel);

        historyLabel = new Label();
        historyLabel.style.fontSize = 22;
        historyLabel.style.color = new Color(0.7f, 0.75f, 0.85f, 1f);
        historyLabel.style.marginTop = 20;
        root.Add(historyLabel);
    }

    public LootReward Roll()
    {
        float total = 0f;
        foreach (LootReward reward in table) total += reward.weight;
        if (total <= 0f) return null;

        float pick = UnityEngine.Random.Range(0f, total);
        foreach (LootReward reward in table)
        {
            pick -= reward.weight;
            if (pick <= 0f) return reward;
        }
        return table[table.Count - 1];
    }

    private void Open()
    {
        LootReward reward = Roll();
        if (reward == null) return;

        int count;
        history.TryGetValue(reward.rewardName, out count);
        history[reward.rewardName] = count + 1;

        resultLabel.text = reward.rewardName;
        resultLabel.style.color = reward.color;

        string text = "";
        foreach (KeyValuePair<string, int> pair in history) text += pair.Key + " x" + pair.Value + "    ";
        historyLabel.text = text;

        if (OnOpened != null) OnOpened(reward);
    }
}
```

The roll picks a number between zero and the total weight and subtracts each reward's weight in turn until the number runs out, so a reward's chance is its weight divided by the sum (60/25/12/3 gives the Legendary a 3% chance). The result is shown in the reward's colour and also raised through `OnOpened` so other systems can grant the item.

**Plan**
- A `VendorNPC` component checks the distance to the player every frame and shows a "Press E to trade" hint within range.
- Pressing E opens a UI Toolkit shop panel listing the vendor's stock with Buy buttons and the player's coin total; leaving range or pressing E again closes it.
- Purchases deduct from a coin value and are limited by what the player can afford.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UIElements;

[Serializable]
public class VendorItem
{
    public string itemName = "Potion";
    public int price = 10;
}

public class VendorNPC : MonoBehaviour
{
    [SerializeField] private Transform player;
    [SerializeField] private float interactRange = 3f;
    [SerializeField] private int playerCoins = 100;
    [SerializeField] private List<VendorItem> stock = new List<VendorItem>
    {
        new VendorItem { itemName = "Health Potion", price = 15 },
        new VendorItem { itemName = "Iron Sword", price = 60 },
        new VendorItem { itemName = "Leather Boots", price = 35 },
    };

    private Label hint;
    private VisualElement shopPanel;
    private Label coinLabel;
    private Label messageLabel;
    private bool shopOpen;

    public event Action<VendorItem> OnItemBought;

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.pickingMode = PickingMode.Ignore;
        root.style.alignItems = Align.Center;
        root.style.justifyContent = Justify.Center;

        hint = new Label("Press E to trade");
        hint.style.position = Position.Absolute;
        hint.style.bottom = 150;
        hint.style.fontSize = 30;
        hint.style.color = Color.white;
        hint.style.display = DisplayStyle.None;
        root.Add(hint);

        shopPanel = new VisualElement();
        shopPanel.style.width = 480;
        shopPanel.style.paddingTop = 20;
        shopPanel.style.paddingBottom = 20;
        shopPanel.style.paddingLeft = 20;
        shopPanel.style.paddingRight = 20;
        shopPanel.style.backgroundColor = new Color(0.1f, 0.12f, 0.17f, 0.95f);
        shopPanel.style.display = DisplayStyle.None;
        root.Add(shopPanel);

        coinLabel = new Label();
        coinLabel.style.fontSize = 30;
        coinLabel.style.color = new Color(1f, 0.85f, 0.3f, 1f);
        shopPanel.Add(coinLabel);

        foreach (VendorItem item in stock)
        {
            VendorItem captured = item;
            Button buy = new Button(() => Buy(captured));
            buy.text = item.itemName + " - " + item.price;
            buy.style.height = 54;
            buy.style.fontSize = 24;
            buy.style.marginTop = 8;
            shopPanel.Add(buy);
        }

        messageLabel = new Label();
        messageLabel.style.fontSize = 22;
        messageLabel.style.color = Color.white;
        messageLabel.style.marginTop = 12;
        shopPanel.Add(messageLabel);
        UpdateCoins();
    }

    private void Update()
    {
        if (player == null) return;
        bool inRange = Vector3.Distance(player.position, transform.position) <= interactRange;
        hint.style.display = inRange && !shopOpen ? DisplayStyle.Flex : DisplayStyle.None;

        if (inRange && Input.GetKeyDown(KeyCode.E)) SetShopOpen(!shopOpen);
        if (shopOpen && !inRange) SetShopOpen(false);
    }

    private void SetShopOpen(bool open)
    {
        shopOpen = open;
        shopPanel.style.display = open ? DisplayStyle.Flex : DisplayStyle.None;
        if (open) messageLabel.text = string.Empty;
    }

    private void Buy(VendorItem item)
    {
        if (playerCoins < item.price)
        {
            messageLabel.text = "Not enough coins.";
            return;
        }
        playerCoins -= item.price;
        UpdateCoins();
        messageLabel.text = "Bought " + item.itemName + "!";
        if (OnItemBought != null) OnItemBought(item);
    }

    private void UpdateCoins()
    {
        coinLabel.text = "Coins: " + playerCoins;
    }
}
```

Put VendorNPC on the NPC and assign the player. Within range a hint appears, E opens the panel, and walking away closes it. Each Buy button checks the player's coins, deducts the price and raises `OnItemBought` so an inventory script can add the item.

