        coinLabel.style.color = new Color(1f, 0.85f, 0.3f, 1f);
        coinLabel.style.marginBottom = 16;
        root.Add(coinLabel);

        list = new VisualElement();
        root.Add(list);
        Refresh();
    }

    public bool Sell(string itemName)
    {
        SellableItem item = items.Find(i => i.itemName == itemName);
        if (item == null || item.owned <= 0) return false;

        item.owned--;
        int value = item.SellValue;
        coins += value;
        if (OnSold != null) OnSold(item, value);
        Refresh();
        return true;
    }

    private void Refresh()
    {
        coinLabel.text = "Coins: " + coins;
        list.Clear();
        foreach (SellableItem item in items)
        {
            if (item.owned <= 0) continue;
            SellableItem captured = item;
            Button sell = new Button(() => Sell(captured.itemName));
            sell.text = item.itemName + " x" + item.owned + "   -   sell for " + item.SellValue;
            sell.style.width = 560;
            sell.style.height = 58;
            sell.style.fontSize = 24;
            sell.style.marginBottom = 8;
            list.Add(sell);
        }
        if (list.childCount == 0)
        {
            Label empty = new Label("Nothing left to sell.");
            empty.style.fontSize = 24;
            empty.style.color = Color.gray;
            list.Add(empty);
        }
    }
}
```

The sell price is computed from the buy price with integer division by two, so it can never exceed half of what the item costs. `Sell` refuses when none are owned, decrements the count, pays the coins and raises `OnSold`; the list is rebuilt afterwards so sold-out items disappear.

**Plan**
- Save the last claim date (UTC ticks) and the current streak in PlayerPrefs.
- A claim is allowed only when today's date is later than the last claim date; claiming the next calendar day extends the streak, any longer gap resets it to day 1, and the 7-day cycle wraps around.
- A UI Toolkit calendar shows seven day cells (claimed, today's reward and future) and a Claim button that disables itself after claiming.

```csharp
using System;
using UnityEngine;
using UnityEngine.UIElements;

public class DailyRewardCalendar : MonoBehaviour
{
    private const string LastClaimKey = "Daily.LastClaimTicks";
    private const string StreakKey = "Daily.Streak";

    [SerializeField] private int[] rewards = { 10, 20, 30, 40, 50, 75, 150 };

    private readonly VisualElement[] cells = new VisualElement[7];
    private Button claimButton;
    private Label statusLabel;

    public event Action<int> OnClaimed;

    private DateTime LastClaimDate
    {
        get
        {
            long ticks;
            if (long.TryParse(PlayerPrefs.GetString(LastClaimKey, ""), out ticks)) return new DateTime(ticks, DateTimeKind.Utc).Date;
            return DateTime.MinValue;
        }
    }

    private int CurrentStreak()
    {
        int streak = PlayerPrefs.GetInt(StreakKey, 0);
        DateTime last = LastClaimDate;
        if (last == DateTime.MinValue) return 0;
        return (DateTime.UtcNow.Date - last).TotalDays > 1.5 ? 0 : streak;
    }

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.style.alignItems = Align.Center;
        root.style.justifyContent = Justify.Center;

        Label title = new Label("Daily Rewards");
        title.style.fontSize = 48;
        title.style.color = Color.white;
        title.style.marginBottom = 24;
        root.Add(title);

        VisualElement row = new VisualElement();
        row.style.flexDirection = FlexDirection.Row;
        root.Add(row);
        for (int i = 0; i < cells.Length; i++)
        {
            VisualElement cell = new VisualElement();
            cell.style.width = 120;
            cell.style.height = 130;
            cell.style.marginLeft = 6;
            cell.style.marginRight = 6;
            cell.style.alignItems = Align.Center;
            cell.style.justifyContent = Justify.Center;
            Label day = new Label("Day " + (i + 1) + "\n+" + rewards[i]);
            day.style.fontSize = 22;
            day.style.color = Color.white;
            day.style.unityTextAlign = TextAnchor.MiddleCenter;
            cell.Add(day);
            cells[i] = cell;
            row.Add(cell);
        }

        claimButton = new Button(Claim);
        claimButton.text = "Claim";
        claimButton.style.width = 320;
        claimButton.style.height = 70;
        claimButton.style.fontSize = 30;
        claimButton.style.marginTop = 24;
        root.Add(claimButton);

        statusLabel = new Label();
        statusLabel.style.fontSize = 24;
        statusLabel.style.color = new Color(0.8f, 0.85f, 0.95f, 1f);
        statusLabel.style.marginTop = 12;
        root.Add(statusLabel);
        Refresh();
    }

    private bool CanClaim()
    {
        return DateTime.UtcNow.Date > LastClaimDate;
    }

    private void Claim()
    {
        if (!CanClaim()) return;
        int streak = CurrentStreak();
        int dayIndex = streak % rewards.Length;
        PlayerPrefs.SetInt(StreakKey, streak + 1);
        PlayerPrefs.SetString(LastClaimKey, DateTime.UtcNow.Ticks.ToString());
        PlayerPrefs.Save();
        if (OnClaimed != null) OnClaimed(rewards[dayIndex]);
        Refresh();
    }

    private void Refresh()
    {
        int streak = CurrentStreak();
        bool canClaim = CanClaim();
        int todayIndex = streak % rewards.Length;

        for (int i = 0; i < cells.Length; i++)
        {
            bool claimed = canClaim ? i < todayIndex : i <= todayIndex;
            bool isToday = canClaim && i == todayIndex;
            cells[i].style.backgroundColor = claimed ? new Color(0.2f, 0.5f, 0.3f, 1f)
                : isToday ? new Color(0.8f, 0.6f, 0.15f, 1f)
                : new Color(0.18f, 0.2f, 0.28f, 1f);
        }

        claimButton.SetEnabled(canClaim);
        statusLabel.text = canClaim ? "Streak: " + streak + " day(s). Reward ready!" : "Come back tomorrow! Streak: " + streak;
    }
}
```

The streak is only valid if the last claim was yesterday or today (a gap of more than a day and a half resets it to zero), and a claim needs today's UTC date to be strictly later than the saved claim date, so it can only happen once per day. The seven cells are coloured for claimed days, today's reward and upcoming days, and `OnClaimed` passes the coin amount to whatever system pays it out.

**Plan**
- Fill an 80x50 boolean grid with random walls (47% density, solid border), then smooth it 5 times: a cell becomes a wall when more than 4 of its 8 neighbours are walls and stays as it was when exactly 4 are.
- Flood-fill every open region and turn all but the largest into wall so the cave is one connected space.
- Build a Grid and Tilemap in code with two runtime-made tiles (wall and floor) and write all cells with a single `SetTiles` call; Space regenerates the cave.

```csharp
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Tilemaps;

public class CellularCave : MonoBehaviour
{
    [SerializeField] private int width = 80;
    [SerializeField] private int height = 50;
    [Range(30, 60)] [SerializeField] private int fillPercent = 47;
    [SerializeField] private int smoothSteps = 5;
    [SerializeField] private string seed = "";
    private static readonly Vector2Int[] Dirs = { Vector2Int.up, Vector2Int.down, Vector2Int.left, Vector2Int.right };
    private Tilemap tilemap;
    private Tile wallTile;
    private Tile floorTile;
    private bool[,] wall;
    private void Start()
    {
        wallTile = MakeTile(new Color(0.16f, 0.14f, 0.18f));
        floorTile = MakeTile(new Color(0.62f, 0.55f, 0.45f));
        GameObject grid = new GameObject("CaveGrid");
        grid.AddComponent<Grid>();
        GameObject map = new GameObject("CaveTilemap");
        map.transform.SetParent(grid.transform, false);
        tilemap = map.AddComponent<Tilemap>();
        map.AddComponent<TilemapRenderer>();
        Generate();
        Camera cam = Camera.main;
        if (cam == null) return;
        cam.orthographic = true;
        cam.orthographicSize = Mathf.Max(height / 2f, width / 2f / cam.aspect) + 1f;
        cam.transform.position = new Vector3(width / 2f, height / 2f, -10f);
    }
    private void Update() { if (Input.GetKeyDown(KeyCode.Space)) Generate(); }
    private static Tile MakeTile(Color color)
    {
        Texture2D tex = new Texture2D(1, 1);
        tex.SetPixel(0, 0, Color.white);
        tex.filterMode = FilterMode.Point;
        tex.Apply();
        Tile tile = ScriptableObject.CreateInstance<Tile>();
        tile.sprite = Sprite.Create(tex, new Rect(0, 0, 1, 1), new Vector2(0.5f, 0.5f), 1f);
        tile.color = color;
        return tile;
    }
    public void Generate()
    {
        System.Random rng = seed.Length > 0 ? new System.Random(StableHash(seed)) : new System.Random();
        wall = new bool[width, height];
        for (int x = 0; x < width; x++)
            for (int y = 0; y < height; y++)
                wall[x, y] = IsEdge(x, y) || rng.Next(0, 100) < fillPercent;
        for (int i = 0; i < smoothSteps; i++) wall = Smooth(wall);
        KeepLargestCavern();
        Draw();
    }
    private static int StableHash(string text)
    {
        int hash = 17;
        foreach (char c in text) hash = hash * 31 + c;
        return hash;
    }
    private bool IsEdge(int x, int y) { return x == 0 || y == 0 || x == width - 1 || y == height - 1; }
    private bool[,] Smooth(bool[,] src)
    {
        bool[,] next = new bool[width, height];
        for (int x = 0; x < width; x++)
        {
            for (int y = 0; y < height; y++)
            {
                int n = CountWalls(src, x, y);
                next[x, y] = IsEdge(x, y) || n > 4 || (n == 4 && src[x, y]);
            }
        }
        return next;
    }
    private int CountWalls(bool[,] map, int cx, int cy)
    {
        int count = 0;
        for (int x = cx - 1; x <= cx + 1; x++)
        {
            for (int y = cy - 1; y <= cy + 1; y++)
            {
                if (x == cx && y == cy) continue;
                if (x < 0 || y < 0 || x >= width || y >= height || map[x, y]) count++;
            }
        }
        return count;
    }
    private void KeepLargestCavern()
    {
        bool[,] seen = new bool[width, height];
        List<List<Vector2Int>> regions = new List<List<Vector2Int>>();
        List<Vector2Int> largest = null;
        for (int x = 0; x < width; x++)
        {
            for (int y = 0; y < height; y++)
            {
                if (wall[x, y] || seen[x, y]) continue;
                List<Vector2Int> region = Flood(x, y, seen);
                regions.Add(region);
                if (largest == null || region.Count > largest.Count) largest = region;
            }
        }
        foreach (List<Vector2Int> region in regions)
            if (region != largest)
                foreach (Vector2Int cell in region) wall[cell.x, cell.y] = true;
    }
    private List<Vector2Int> Flood(int sx, int sy, bool[,] seen)
    {
        List<Vector2Int> region = new List<Vector2Int>();
        Queue<Vector2Int> queue = new Queue<Vector2Int>();
        queue.Enqueue(new Vector2Int(sx, sy));
        seen[sx, sy] = true;
        while (queue.Count > 0)
        {
            Vector2Int cell = queue.Dequeue();
            region.Add(cell);
            foreach (Vector2Int d in Dirs)
            {
                Vector2Int n = cell + d;
                if (n.x < 0 || n.y < 0 || n.x >= width || n.y >= height || wall[n.x, n.y] || seen[n.x, n.y]) continue;
                seen[n.x, n.y] = true;
                queue.Enqueue(n);
            }
        }
        return region;
    }
    private void Draw()
    {
        Vector3Int[] positions = new Vector3Int[width * height];
        TileBase[] tiles = new TileBase[width * height];
        int i = 0;
        for (int x = 0; x < width; x++)
        {
            for (int y = 0; y < height; y++)
            {
                positions[i] = new Vector3Int(x, y, 0);
                tiles[i] = wall[x, y] ? wallTile : floorTile;
                i++;
            }
        }
        tilemap.ClearAllTiles();
        tilemap.SetTiles(positions, tiles);
    }
}
```

Random fill produces noise; each smoothing pass lets every cell adopt the majority of its 3x3 neighbourhood, so after five passes the speckles merge into rounded caverns and ragged walls. Wall tiles outside the largest open region are filled in, which guarantees the player can reach every floor tile, and a non-empty `seed` string gives repeatable caves (the hash is computed by hand because `string.GetHashCode` is not stable across platforms).

**Plan**
- Create a `TerrainData` (257 heightmap, 500x80x500), fill it with 5-octave Perlin noise and instantiate it with `Terrain.CreateTerrainGameObject`.
- Make three `TerrainLayer`s (grass, rock, snow) with small procedural textures.
- For every alphamap cell, weigh the layers by normalised height (grass low, rock mid, snow high) plus slope (steep ground turns to rock), normalise the weights and write them with `SetAlphamaps`; Space rebuilds with a new seed.

```csharp
using UnityEngine;

public class PerlinTerrainPainter : MonoBehaviour
{
    [SerializeField] private int heightmapResolution = 257;
    [SerializeField] private int alphamapResolution = 256;
    [SerializeField] private Vector3 size = new Vector3(500f, 80f, 500f);
    [SerializeField] private float noiseScale = 3f;
    [SerializeField] private int octaves = 5;
    [Range(0.1f, 0.5f)] [SerializeField] private float grassEnd = 0.3f;
    [Range(0.4f, 0.9f)] [SerializeField] private float snowStart = 0.62f;

    private GameObject terrainObject;
    private int seed = 1;

    private void Start()
    {
        Build();
        Camera cam = Camera.main;
        if (cam == null) return;
        cam.transform.position = new Vector3(size.x * 0.5f, size.y * 2f, -size.z * 0.2f);
        cam.transform.LookAt(new Vector3(size.x * 0.5f, size.y * 0.3f, size.z * 0.5f));
    }

    private void Update()
    {
        if (Input.GetKeyDown(KeyCode.Space))
        {
            seed++;
            Build();
        }
    }

    private void Build()
    {
        if (terrainObject != null) Destroy(terrainObject);

        TerrainData data = new TerrainData();
        data.heightmapResolution = heightmapResolution;
        data.alphamapResolution = alphamapResolution;
        data.size = size;
        data.SetHeights(0, 0, BuildHeights());
        data.terrainLayers = new TerrainLayer[]
        {
            MakeLayer("Grass", new Color(0.18f, 0.45f, 0.14f), new Color(0.3f, 0.6f, 0.2f)),
            MakeLayer("Rock", new Color(0.35f, 0.33f, 0.32f), new Color(0.55f, 0.52f, 0.5f)),
            MakeLayer("Snow", new Color(0.85f, 0.88f, 0.92f), new Color(1f, 1f, 1f)),
        };
        Paint(data);

        terrainObject = Terrain.CreateTerrainGameObject(data);
        terrainObject.name = "PerlinTerrain";
    }

    private float[,] BuildHeights()
    {
        int res = heightmapResolution;
        float[,] heights = new float[res, res];
        float offsetX = seed * 137.5f;
        float offsetY = seed * 91.3f;
        for (int y = 0; y < res; y++)
        {
            for (int x = 0; x < res; x++)
            {
                float amplitude = 1f, frequency = 1f, value = 0f, total = 0f;
                for (int o = 0; o < octaves; o++)
                {
                    float sx = (float)x / res * noiseScale * frequency + offsetX;
                    float sy = (float)y / res * noiseScale * frequency + offsetY;
                    value += Mathf.PerlinNoise(sx, sy) * amplitude;
                    total += amplitude;
                    amplitude *= 0.5f;
                    frequency *= 2f;
                }
                heights[y, x] = Mathf.Pow(value / total, 1.6f);
            }
        }
        return heights;
    }

    private void Paint(TerrainData data)
    {
        int res = alphamapResolution;
        float[,,] maps = new float[res, res, 3];
        for (int y = 0; y < res; y++)
        {
            for (int x = 0; x < res; x++)
            {
                float nx = (float)x / (res - 1);
                float ny = (float)y / (res - 1);
                float h = data.GetInterpolatedHeight(nx, ny) / size.y;
                float slope = Mathf.Clamp01(data.GetSteepness(nx, ny) / 40f);

                float snow = Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(snowStart, snowStart + 0.1f, h)) * (1f - slope * 0.6f);
                float grass = (1f - Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(grassEnd - 0.1f, grassEnd, h))) * (1f - slope);
                float rock = Mathf.Max(0.001f, 1f - snow - grass);
                float sum = grass + rock + snow;
                maps[y, x, 0] = grass / sum;
                maps[y, x, 1] = rock / sum;
                maps[y, x, 2] = snow / sum;
            }
        }
        data.SetAlphamaps(0, 0, maps);
    }

    private static TerrainLayer MakeLayer(string layerName, Color a, Color b)
    {
        Texture2D tex = new Texture2D(64, 64);
        for (int y = 0; y < 64; y++)
            for (int x = 0; x < 64; x++)
                tex.SetPixel(x, y, Color.Lerp(a, b, Mathf.PerlinNoise(x * 0.25f, y * 0.25f)));
        tex.wrapMode = TextureWrapMode.Repeat;
        tex.Apply();

        TerrainLayer layer = new TerrainLayer();
        layer.name = layerName;
        layer.diffuseTexture = tex;
        layer.tileSize = new Vector2(12f, 12f);
        return layer;
    }
}
```

The heights come from five octaves of Perlin noise (each octave doubles the frequency and halves the amplitude), raised to a power so valleys are wide and peaks are sharp. For painting, each splat cell reads its normalised height and slope: grass fades out below `grassEnd`, snow fades in above `snowStart`, steep faces lose grass and snow, and rock takes the remainder; the weights are normalised so they always sum to 1. Note that heightmaps and alphamaps are indexed `[y, x]`; with URP, assign a URP Terrain Lit material to the terrain if it looks pink.

**Plan**
- Keep a byte grid (0 empty, 1 room, 2 corridor) and try up to 200 random rooms of 5-11 cells, rejecting any that overlap an existing room plus a one-cell margin.
- Connect each room to the previous one with an L-shaped corridor between their centres, randomly going horizontal-first or vertical-first.
- Render each horizontal run of identical cells as one scaled cube (rooms grey, corridors brown), frame a top-down camera and let Space generate the next seed.

```csharp
using System.Collections.Generic;
using UnityEngine;

public class DungeonGenerator : MonoBehaviour
{
    [SerializeField] private int gridWidth = 64;
    [SerializeField] private int gridHeight = 48;
    [SerializeField] private int maxRooms = 12;
    [SerializeField] private Vector2Int roomSizeRange = new Vector2Int(5, 11);
    [SerializeField] private int seed = 1;

    private const byte Room = 1;
    private const byte Corridor = 2;
    private readonly List<RectInt> rooms = new List<RectInt>();
    private byte[,] map;
    private Transform holder;
    private System.Random rng;

    private void Start()
    {
        Generate();
        Camera cam = Camera.main;
        if (cam == null) return;
        cam.orthographic = true;
        cam.orthographicSize = gridHeight / 2f + 2f;
        cam.transform.position = new Vector3(gridWidth / 2f, 50f, gridHeight / 2f);
        cam.transform.rotation = Quaternion.Euler(90f, 0f, 0f);
    }

    private void Update()
    {
        if (!Input.GetKeyDown(KeyCode.Space)) return;
        seed++;
        Generate();
    }

    public void Generate()
    {
        rng = new System.Random(seed);
        map = new byte[gridWidth, gridHeight];
        rooms.Clear();

        for (int attempt = 0; attempt < 200 && rooms.Count < maxRooms; attempt++)
        {
            int w = rng.Next(roomSizeRange.x, roomSizeRange.y + 1);
            int h = rng.Next(roomSizeRange.x, roomSizeRange.y + 1);
            RectInt room = new RectInt(rng.Next(1, gridWidth - w - 1), rng.Next(1, gridHeight - h - 1), w, h);
            if (OverlapsExisting(room)) continue;
            rooms.Add(room);
            for (int x = room.xMin; x < room.xMax; x++)
                for (int y = room.yMin; y < room.yMax; y++)
                    map[x, y] = Room;
        }

        for (int i = 1; i < rooms.Count; i++)
        {
            Vector2Int a = Vector2Int.FloorToInt(rooms[i - 1].center);
            Vector2Int b = Vector2Int.FloorToInt(rooms[i].center);
            if (rng.Next(2) == 0)
            {
                CarveHorizontal(a.x, b.x, a.y);
                CarveVertical(a.y, b.y, b.x);
            }
            else
            {
                CarveVertical(a.y, b.y, a.x);
                CarveHorizontal(a.x, b.x, b.y);
            }
        }
        Render();
    }

    private bool OverlapsExisting(RectInt room)
    {
        foreach (RectInt other in rooms)
        {
            RectInt padded = new RectInt(other.x - 1, other.y - 1, other.width + 2, other.height + 2);
            if (padded.Overlaps(room)) return true;
        }
        return false;
    }

    private void CarveHorizontal(int x1, int x2, int y)
    {
        for (int x = Mathf.Min(x1, x2); x <= Mathf.Max(x1, x2); x++)
            if (map[x, y] == 0) map[x, y] = Corridor;
    }

    private void CarveVertical(int y1, int y2, int x)
    {
        for (int y = Mathf.Min(y1, y2); y <= Mathf.Max(y1, y2); y++)
            if (map[x, y] == 0) map[x, y] = Corridor;
    }

    private void Render()
    {
        if (holder != null) Destroy(holder.gameObject);
        holder = new GameObject("Dungeon").transform;
        for (int y = 0; y < gridHeight; y++)
        {
            int x = 0;
            while (x < gridWidth)
            {
                byte kind = map[x, y];
                if (kind == 0)
                {
                    x++;
                    continue;
                }
                int start = x;
                while (x < gridWidth && map[x, y] == kind) x++;
                CreateStrip(start, x, y, kind);
            }
        }
    }

    private void CreateStrip(int x0, int x1, int y, byte kind)
    {
        GameObject cube = GameObject.CreatePrimitive(PrimitiveType.Cube);
        cube.name = kind == Room ? "RoomStrip" : "CorridorStrip";
        cube.transform.SetParent(holder, false);
        float length = x1 - x0;
        cube.transform.localScale = new Vector3(length, 0.2f, 1f);
        cube.transform.localPosition = new Vector3(x0 + length / 2f, 0f, y + 0.5f);
        cube.GetComponent<Renderer>().material.color = kind == Room
            ? new Color(0.6f, 0.62f, 0.68f)
            : new Color(0.45f, 0.32f, 0.2f);
    }
}
```

Rooms are only accepted when their one-cell-padded neighbours do not overlap, which keeps walls between them. Each room is joined to the previous one by an L-shaped corridor (one horizontal and one vertical leg meeting at a corner, with a random leg first), so every room is reachable from the first one. Merging each horizontal run of cells into one stretched cube keeps the object count low instead of creating a cube per tile.

**Plan**
- Keep one pool (a `Queue<GameObject>`) per track prefab; if no prefabs are assigned, build two default templates (plain road and road with an obstacle) from primitives.
- Each frame the runner moves forward on Z (A/D strafes); the spawner places random segments until the track reaches `spawnAhead` studs in front of the player.
- Segments that are `despawnBehind` units behind the player are deactivated and returned to their prefab's pool instead of being destroyed.

```csharp
using System.Collections.Generic;
using UnityEngine;

public class EndlessRunnerTrack : MonoBehaviour
{
    [SerializeField] private Transform player;
    [SerializeField] private GameObject[] trackPrefabs;
    [SerializeField] private float segmentLength = 30f;
    [SerializeField] private float spawnAhead = 120f;
    [SerializeField] private float despawnBehind = 40f;
    [SerializeField] private float runSpeed = 12f;
    [SerializeField] private float strafeSpeed = 8f;
    [SerializeField] private float laneLimit = 4f;

    private class Segment
    {
        public GameObject prefab;
        public GameObject instance;
    }

    private readonly Dictionary<GameObject, Queue<GameObject>> pools = new Dictionary<GameObject, Queue<GameObject>>();
    private readonly LinkedList<Segment> active = new LinkedList<Segment>();
    private float nextZ;

    private void Awake()
    {
        if (player == null)
        {
            GameObject runner = GameObject.CreatePrimitive(PrimitiveType.Capsule);
            runner.name = "Runner";
            runner.transform.position = new Vector3(0f, 1.5f, 0f);
            player = runner.transform;
        }
        if (trackPrefabs == null || trackPrefabs.Length == 0) trackPrefabs = BuildDefaultPrefabs();
        nextZ = -segmentLength / 2f;
    }

    private GameObject[] BuildDefaultPrefabs()
    {
        GameObject[] templates = new GameObject[2];
        for (int i = 0; i < templates.Length; i++)
        {
            GameObject root = new GameObject("TrackTemplate" + i);
            GameObject floor = GameObject.CreatePrimitive(PrimitiveType.Cube);
            floor.transform.SetParent(root.transform, false);
            floor.transform.localPosition = new Vector3(0f, -0.5f, 0f);
            floor.transform.localScale = new Vector3(12f, 1f, segmentLength);
            floor.GetComponent<Renderer>().material.color = i == 0 ? new Color(0.3f, 0.3f, 0.34f) : new Color(0.24f, 0.26f, 0.32f);
            if (i == 1)
            {
                GameObject block = GameObject.CreatePrimitive(PrimitiveType.Cube);
                block.transform.SetParent(root.transform, false);
                block.transform.localPosition = new Vector3(0f, 1f, 0f);
                block.transform.localScale = new Vector3(3f, 2f, 1.5f);
                block.GetComponent<Renderer>().material.color = new Color(0.9f, 0.25f, 0.2f);
            }
            root.transform.SetParent(transform, false);
            root.SetActive(false);
            templates[i] = root;
        }
        return templates;
    }

    private void Update()
    {
        Vector3 p = player.position;
        p.z += runSpeed * Time.deltaTime;
        p.x = Mathf.Clamp(p.x + Input.GetAxis("Horizontal") * strafeSpeed * Time.deltaTime, -laneLimit, laneLimit);
        player.position = p;

        while (nextZ < p.z + spawnAhead) SpawnSegment();
        while (active.Count > 0 && active.First.Value.instance.transform.position.z + segmentLength / 2f < p.z - despawnBehind)
            ReleaseOldest();
    }

    private void SpawnSegment()
    {
        GameObject prefab = trackPrefabs[Random.Range(0, trackPrefabs.Length)];
        Queue<GameObject> pool;
        if (!pools.TryGetValue(prefab, out pool))
        {
            pool = new Queue<GameObject>();
            pools[prefab] = pool;
        }
        GameObject instance = pool.Count > 0 ? pool.Dequeue() : Instantiate(prefab, transform);
        instance.transform.position = new Vector3(0f, 0f, nextZ + segmentLength / 2f);
        instance.SetActive(true);
        active.AddLast(new Segment { prefab = prefab, instance = instance });
        nextZ += segmentLength;
    }

    private void ReleaseOldest()
    {
        Segment oldest = active.First.Value;
        active.RemoveFirst();
        oldest.instance.SetActive(false);
        pools[oldest.prefab].Enqueue(oldest.instance);
    }
}
```

Segments are only ever created when the pool for that prefab is empty, so after the first few seconds the runner recycles the same handful of objects with no `Instantiate` or `Destroy` calls. The spawn loop keeps the track `spawnAhead` units in front of the player and the release loop returns the oldest segment once it is fully behind them, which keeps both lists in order.

**Plan**
- Run Bridson's Poisson disc sampling over the terrain's X/Z size: a background grid with cell size `minDistance / sqrt(2)` makes each distance check look at only a 5x5 block of cells.
- Skip any point where `GetSteepness` exceeds the slope limit, then place a random prefab at `SampleHeight` with random yaw and scale.
- With no prefabs assigned it creates inactive tree and rock templates from primitives; the seed makes the layout repeatable.

```csharp
using System.Collections.Generic;
using UnityEngine;

public class PoissonVegetation : MonoBehaviour
{
    [SerializeField] private Terrain terrain;
    [SerializeField] private GameObject[] prefabs;
    [SerializeField] private float minDistance = 6f;
    [SerializeField] private int candidatesPerPoint = 30;
    [SerializeField] private float maxSlope = 30f;
    [SerializeField] private Vector2 scaleRange = new Vector2(0.8f, 1.4f);
    [SerializeField] private int seed = 1;

    private void Start()
    {
        if (terrain == null) terrain = Terrain.activeTerrain;
        if (terrain == null) return;
        if (prefabs == null || prefabs.Length == 0) prefabs = BuildDefaults();
        Scatter();
    }

    private void Scatter()
    {
        System.Random rng = new System.Random(seed);
        TerrainData data = terrain.terrainData;
        Vector3 origin = terrain.transform.position;
        Transform holder = new GameObject("Vegetation").transform;
        foreach (Vector2 point in SamplePoints(data.size.x, data.size.z, rng))
        {
            if (data.GetSteepness(point.x / data.size.x, point.y / data.size.z) > maxSlope) continue;
            Vector3 pos = new Vector3(origin.x + point.x, 0f, origin.z + point.y);
            pos.y = terrain.SampleHeight(pos) + origin.y;
            GameObject prefab = prefabs[rng.Next(prefabs.Length)];
            GameObject plant = Instantiate(prefab, pos, Quaternion.Euler(0f, (float)rng.NextDouble() * 360f, 0f), holder);
            plant.transform.localScale = Vector3.one * (scaleRange.x + (float)rng.NextDouble() * (scaleRange.y - scaleRange.x));
            plant.SetActive(true);
        }
    }

    private List<Vector2> SamplePoints(float width, float height, System.Random rng)
    {
        float cell = minDistance / Mathf.Sqrt(2f);
        int cols = Mathf.CeilToInt(width / cell);
        int rows = Mathf.CeilToInt(height / cell);
        int[,] grid = new int[cols, rows];
        List<Vector2> points = new List<Vector2>();
        List<Vector2> frontier = new List<Vector2>();

        void Add(Vector2 p)
        {
            points.Add(p);
            frontier.Add(p);
            grid[Mathf.Min(cols - 1, (int)(p.x / cell)), Mathf.Min(rows - 1, (int)(p.y / cell))] = points.Count;
        }

        bool IsFree(Vector2 p)
        {
            int gx = Mathf.Min(cols - 1, (int)(p.x / cell));
            int gy = Mathf.Min(rows - 1, (int)(p.y / cell));
            for (int x = Mathf.Max(0, gx - 2); x <= Mathf.Min(cols - 1, gx + 2); x++)
            {
                for (int y = Mathf.Max(0, gy - 2); y <= Mathf.Min(rows - 1, gy + 2); y++)
                {
                    int index = grid[x, y];
                    if (index > 0 && (points[index - 1] - p).sqrMagnitude < minDistance * minDistance) return false;
                }
            }
            return true;
        }

        Add(new Vector2((float)rng.NextDouble() * width, (float)rng.NextDouble() * height));
        while (frontier.Count > 0)
        {
            int pick = rng.Next(frontier.Count);
            Vector2 center = frontier[pick];
            bool placed = false;
            for (int i = 0; i < candidatesPerPoint && !placed; i++)
            {
                float angle = (float)rng.NextDouble() * Mathf.PI * 2f;
                float radius = minDistance * (1f + (float)rng.NextDouble());
                Vector2 candidate = center + new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * radius;
                if (candidate.x < 0f || candidate.y < 0f || candidate.x >= width || candidate.y >= height) continue;
                if (!IsFree(candidate)) continue;
                Add(candidate);
                placed = true;
            }
            if (!placed) frontier.RemoveAt(pick);
        }
        return points;
    }

    private GameObject[] BuildDefaults()
    {
        GameObject tree = new GameObject("TreeTemplate");
        AddPart(tree.transform, PrimitiveType.Cylinder, new Vector3(0f, 1.5f, 0f), new Vector3(0.5f, 1.5f, 0.5f), new Color(0.4f, 0.27f, 0.15f));
        AddPart(tree.transform, PrimitiveType.Sphere, new Vector3(0f, 3.8f, 0f), new Vector3(3f, 3f, 3f), new Color(0.2f, 0.5f, 0.2f));
        GameObject rock = new GameObject("RockTemplate");
        AddPart(rock.transform, PrimitiveType.Sphere, new Vector3(0f, 0.4f, 0f), new Vector3(1.6f, 1f, 1.3f), new Color(0.5f, 0.5f, 0.52f));
        tree.transform.SetParent(transform, false);
        rock.transform.SetParent(transform, false);
        tree.SetActive(false);
        rock.SetActive(false);
        return new GameObject[] { tree, tree, rock };
    }

    private static void AddPart(Transform parent, PrimitiveType type, Vector3 position, Vector3 scale, Color color)
    {
        GameObject part = GameObject.CreatePrimitive(type);
        part.transform.SetParent(parent, false);
        part.transform.localPosition = position;
        part.transform.localScale = scale;
        part.GetComponent<Renderer>().material.color = color;
    }
}
```

Poisson disc sampling guarantees that no two points are closer than `minDistance`, so with a prefab radius under half of that nothing can overlap, yet the layout still looks natural rather than gridded. Every new point comes from a ring between one and two minimum distances around a random existing point, and a point is dropped from the frontier after 30 failed attempts. Terrain steepness is read in 0-1 coordinates and `SampleHeight` puts each plant on the real surface.

**Plan**
- Build a hexagonal prism `Mesh` once in code and share it between all tiles, one `Material` per biome (copied from the pipeline's default material so it works in any render pipeline).
- For every axial coordinate inside the map radius, sample two Perlin layers, height (with a gentle edge falloff to form islands) and moisture, and classify the tile.
- Ocean and beach come from low height, mountain and snow from high height, and the middle band is split by moisture into desert, grassland, forest and jungle; tile height follows elevation. Space regenerates with a new seed.

```csharp
using System.Collections.Generic;
using UnityEngine;

public class HexBiomeMap : MonoBehaviour
{
    private enum Biome { Ocean, Beach, Desert, Grassland, Forest, Jungle, Mountain, Snow }

    [SerializeField] private int mapRadius = 22;
    [SerializeField] private float hexSize = 1f;
    [SerializeField] private float heightFrequency = 0.045f;
    [SerializeField] private float moistureFrequency = 0.08f;
    [SerializeField] private float maxTileHeight = 5f;
    [SerializeField] private int seed = 1;

    private readonly Dictionary<Biome, Material> materials = new Dictionary<Biome, Material>();
    private Mesh hexMesh;
    private Transform holder;

    private void Start()
    {
        hexMesh = BuildHexMesh();
        GameObject probe = GameObject.CreatePrimitive(PrimitiveType.Cube);
        Material baseMaterial = probe.GetComponent<Renderer>().sharedMaterial;
        Destroy(probe);
        AddMaterial(baseMaterial, Biome.Ocean, new Color(0.1f, 0.3f, 0.7f));
        AddMaterial(baseMaterial, Biome.Beach, new Color(0.9f, 0.85f, 0.55f));
        AddMaterial(baseMaterial, Biome.Desert, new Color(0.85f, 0.7f, 0.35f));
        AddMaterial(baseMaterial, Biome.Grassland, new Color(0.45f, 0.75f, 0.3f));
        AddMaterial(baseMaterial, Biome.Forest, new Color(0.15f, 0.5f, 0.2f));
        AddMaterial(baseMaterial, Biome.Jungle, new Color(0.05f, 0.35f, 0.15f));
        AddMaterial(baseMaterial, Biome.Mountain, new Color(0.5f, 0.48f, 0.47f));
        AddMaterial(baseMaterial, Biome.Snow, new Color(0.95f, 0.97f, 1f));
        Generate();
    }

    private void Update()
    {
        if (!Input.GetKeyDown(KeyCode.Space)) return;
        seed++;
        Generate();
    }

    private void AddMaterial(Material source, Biome biome, Color color)
    {
        Material material = new Material(source);
        material.color = color;
        materials[biome] = material;
    }

    private static Mesh BuildHexMesh()
    {
        Vector3[] corners = new Vector3[6];
        for (int i = 0; i < 6; i++)
        {
            float angle = Mathf.Deg2Rad * (60f * i - 30f);
            corners[i] = new Vector3(Mathf.Cos(angle), 0f, Mathf.Sin(angle));
        }
        List<Vector3> vertices = new List<Vector3>();
        List<int> triangles = new List<int>();
        int center = vertices.Count;
        vertices.Add(Vector3.up);
        for (int i = 0; i < 6; i++) vertices.Add(corners[i] + Vector3.up);
        for (int i = 0; i < 6; i++)
        {
            triangles.Add(center);
            triangles.Add(center + 1 + (i + 1) % 6);
            triangles.Add(center + 1 + i);
        }
        for (int i = 0; i < 6; i++)
        {
            Vector3 a = corners[i];
            Vector3 b = corners[(i + 1) % 6];
            int s = vertices.Count;
            vertices.Add(a);
            vertices.Add(b);
            vertices.Add(b + Vector3.up);
            vertices.Add(a + Vector3.up);
            triangles.AddRange(new[] { s, s + 1, s + 2, s, s + 2, s + 3 });
        }
        Mesh mesh = new Mesh { name = "HexPrism" };
        mesh.SetVertices(vertices);
        mesh.SetTriangles(triangles, 0);
        mesh.RecalculateNormals();
        mesh.RecalculateBounds();
        return mesh;
    }

    private float Fractal(float x, float z, float frequency, float offset)
    {
        float value = 0f, amplitude = 1f, total = 0f;
        for (int o = 0; o < 3; o++)
        {
            value += Mathf.PerlinNoise(x * frequency + offset + 1000f, z * frequency + offset + 1000f) * amplitude;
            total += amplitude;
            amplitude *= 0.5f;
            frequency *= 2f;
        }
        return value / total;
    }

    private static Biome Classify(float height, float moisture)
    {
        if (height < 0.3f) return Biome.Ocean;
        if (height < 0.35f) return Biome.Beach;
        if (height > 0.78f) return Biome.Snow;
        if (height > 0.65f) return Biome.Mountain;
        if (moisture < 0.33f) return Biome.Desert;
        if (moisture < 0.55f) return Biome.Grassland;
        return moisture < 0.75f ? Biome.Forest : Biome.Jungle;
    }

    private void Generate()
    {
        if (holder != null) Destroy(holder.gameObject);
        holder = new GameObject("HexMap").transform;
        float heightOffset = seed * 173.1f;
        float moistureOffset = seed * 311.7f + 500f;

        for (int q = -mapRadius; q <= mapRadius; q++)
        {
            for (int r = Mathf.Max(-mapRadius, -q - mapRadius); r <= Mathf.Min(mapRadius, -q + mapRadius); r++)
            {
                float x = hexSize * Mathf.Sqrt(3f) * (q + r / 2f);
                float z = hexSize * 1.5f * r;
                float edge = (Mathf.Abs(q) + Mathf.Abs(r) + Mathf.Abs(q + r)) / 2f / mapRadius;
                float height = Mathf.Clamp01(Fractal(x, z, heightFrequency, heightOffset) - edge * edge * 0.35f);
                float moisture = Fractal(x, z, moistureFrequency, moistureOffset);
                Biome biome = Classify(height, moisture);

                GameObject tile = new GameObject("Hex " + q + "," + r + " " + biome);
                tile.transform.SetParent(holder, false);
                tile.transform.localPosition = new Vector3(x, 0f, z);
                float tileHeight = biome == Biome.Ocean ? 0.3f : 0.4f + height * maxTileHeight;
                tile.transform.localScale = new Vector3(hexSize, tileHeight, hexSize);
                tile.AddComponent<MeshFilter>().sharedMesh = hexMesh;
                tile.AddComponent<MeshRenderer>().sharedMaterial = materials[biome];
            }
        }
    }
}
```

Height decides land versus sea and mountains versus lowlands, and moisture only splits the middle band into desert, grassland, forest and jungle, so the same two layers give believable neighbouring biomes. Tiles use axial coordinates (q, r) converted to pointy-top positions, and the radius loop keeps the map a hexagon. The prism mesh is built once and shared, and the biome material is cloned from Unity's default so colours work in built-in, URP or HDRP.

**Plan**
- A `timeOfDay` value from 0 to 1 advances with `Time.deltaTime / 300`; the sun is rotated to `timeOfDay * 360 - 90` degrees so noon is straight down and midnight is straight up.
- A colour `Gradient` built in code and the sun's elevation (`sin`) drive the light's colour and intensity; ambient intensity and fog colour follow, and shadows switch off at night.
- A UI Toolkit label shows the 24-hour clock.

```csharp
using UnityEngine;
using UnityEngine.UIElements;

public class DayNightCycle : MonoBehaviour
{
    [SerializeField] private Light sun;
    [SerializeField] private float dayLengthSeconds = 300f;
    [Range(0f, 1f)] [SerializeField] private float timeOfDay = 0.3f;
    [SerializeField] private float maxIntensity = 1.2f;

    private Gradient sunColor;
    private Color nightFog = new Color(0.02f, 0.03f, 0.08f);
    private Color dayFog = new Color(0.6f, 0.72f, 0.85f);
    private Label clockLabel;

    private void Start()
    {
        if (sun == null)
        {
            foreach (Light candidate in FindObjectsOfType<Light>())
            {
                if (candidate.type == LightType.Directional)
                {
                    sun = candidate;
                    break;
                }
            }
        }
        if (sun == null)
        {
            GameObject go = new GameObject("Sun");
            sun = go.AddComponent<Light>();
            sun.type = LightType.Directional;
        }
        sunColor = BuildGradient();
        RenderSettings.fog = true;
        RenderSettings.fogMode = FogMode.Exponential;
        RenderSettings.fogDensity = 0.004f;
        BuildClock();
        Apply();
    }

    private void Update()
    {
        timeOfDay = Mathf.Repeat(timeOfDay + Time.deltaTime / dayLengthSeconds, 1f);
        Apply();
    }

    private static Gradient BuildGradient()
    {
        Gradient gradient = new Gradient();
        gradient.SetKeys(
            new GradientColorKey[]
            {
                new GradientColorKey(new Color(0.05f, 0.07f, 0.18f), 0f),
                new GradientColorKey(new Color(0.9f, 0.45f, 0.25f), 0.23f),
                new GradientColorKey(new Color(1f, 0.95f, 0.85f), 0.38f),
                new GradientColorKey(new Color(1f, 0.97f, 0.92f), 0.5f),
                new GradientColorKey(new Color(1f, 0.85f, 0.65f), 0.65f),
                new GradientColorKey(new Color(0.95f, 0.4f, 0.2f), 0.77f),
                new GradientColorKey(new Color(0.05f, 0.07f, 0.18f), 1f),
            },
            new GradientAlphaKey[] { new GradientAlphaKey(1f, 0f), new GradientAlphaKey(1f, 1f) });
        return gradient;
    }

    private void Apply()
    {
        float elevation = Mathf.Sin((timeOfDay - 0.25f) * Mathf.PI * 2f);
        float daylight = Mathf.Clamp01(elevation * 2f);

        sun.transform.rotation = Quaternion.Euler(timeOfDay * 360f - 90f, 30f, 0f);
        sun.color = sunColor.Evaluate(timeOfDay);
        sun.intensity = Mathf.Clamp01(elevation) * maxIntensity;
        sun.shadows = elevation > 0.05f ? LightShadows.Soft : LightShadows.None;

        RenderSettings.ambientIntensity = Mathf.Lerp(0.15f, 1f, daylight);
        RenderSettings.fogColor = Color.Lerp(nightFog, dayFog, daylight);

        if (clockLabel != null)
        {
            float hours = timeOfDay * 24f;
            int h = Mathf.FloorToInt(hours);
            int m = Mathf.FloorToInt((hours - h) * 60f);
            clockLabel.text = h.ToString("00") + ":" + m.ToString("00");
        }
    }

    private void BuildClock()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }
        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.pickingMode = PickingMode.Ignore;
        clockLabel = new Label();
        clockLabel.style.position = Position.Absolute;
        clockLabel.style.top = 20;
        clockLabel.style.right = 30;
        clockLabel.style.fontSize = 40;
        clockLabel.style.color = Color.white;
        root.Add(clockLabel);
    }
}
```

One full rotation of the sun takes `dayLengthSeconds` (300 s, five minutes), starting at about 07:00. The sine of the sun's angle gives its elevation: intensity is that value clamped at zero, so the light fades to nothing at dusk, while the gradient supplies the orange sunrise and sunset tint. Ambient strength, fog colour and shadows follow the same value, and the clock label converts the 0-1 time into HH:MM.

**Plan**
- World space is split into chunks of 16x16 cells; every frame the player's chunk coordinate is checked, and only when it changes does the script queue every chunk inside `viewDistance` (nearest first) and unload chunks beyond `viewDistance + 1`.
- Each chunk is a heightfield mesh whose heights come from Perlin noise sampled in world coordinates, so neighbouring chunks share their edge heights exactly.
- At most two chunks are built per frame, and unloaded chunk objects go to a pool and are reused with their mesh.

```csharp
using System.Collections.Generic;
using UnityEngine;

public class InfiniteChunkWorld : MonoBehaviour
{
    [SerializeField] private Transform player;
    [SerializeField] private int chunkSize = 16;
    [SerializeField] private float cellSize = 2f;
    [SerializeField] private int viewDistance = 4;
    [SerializeField] private int chunksPerFrame = 2;
    [SerializeField] private float noiseScale = 0.02f;
    [SerializeField] private float heightScale = 14f;

    private readonly Dictionary<Vector2Int, GameObject> loaded = new Dictionary<Vector2Int, GameObject>();
    private readonly Stack<GameObject> pool = new Stack<GameObject>();
    private readonly Queue<Vector2Int> pending = new Queue<Vector2Int>();
    private Vector2Int lastCenter = new Vector2Int(int.MaxValue, int.MaxValue);
    private Vector3[] vertices;
    private int[] triangles;
    private Material material;

    private float ChunkWorldSize { get { return chunkSize * cellSize; } }
    private void Start()
    {
        if (player == null && Camera.main != null) player = Camera.main.transform;
        GameObject probe = GameObject.CreatePrimitive(PrimitiveType.Cube);
        material = new Material(probe.GetComponent<Renderer>().sharedMaterial);
        material.color = new Color(0.35f, 0.6f, 0.3f);
        Destroy(probe);

        int row = chunkSize + 1;
        vertices = new Vector3[row * row];
        triangles = new int[chunkSize * chunkSize * 6];
        int t = 0;
        for (int z = 0; z < chunkSize; z++)
        {
            for (int x = 0; x < chunkSize; x++)
            {
                int i = z * row + x;
                triangles[t++] = i;
                triangles[t++] = i + row;
                triangles[t++] = i + 1;
                triangles[t++] = i + 1;
                triangles[t++] = i + row;
                triangles[t++] = i + row + 1;
            }
        }
    }

    public float HeightAt(float x, float z)
    {
        float h = Mathf.PerlinNoise(x * noiseScale + 50000f, z * noiseScale + 50000f);
        h += 0.35f * Mathf.PerlinNoise(x * noiseScale * 3f + 50000f, z * noiseScale * 3f + 50000f);
        return h * heightScale;
    }

    private void Update()
    {
        if (player == null) return;
        Vector2Int center = new Vector2Int(
            Mathf.FloorToInt(player.position.x / ChunkWorldSize),
            Mathf.FloorToInt(player.position.z / ChunkWorldSize));
        if (center != lastCenter)
        {
            lastCenter = center;
            QueueChunks(center);
            UnloadFar(center);
        }
        for (int i = 0; i < chunksPerFrame && pending.Count > 0; i++)
        {
            Vector2Int coord = pending.Dequeue();
            if (!loaded.ContainsKey(coord)) CreateChunk(coord);
        }
    }

    private void QueueChunks(Vector2Int center)
    {
        pending.Clear();
        List<Vector2Int> needed = new List<Vector2Int>();
        for (int dx = -viewDistance; dx <= viewDistance; dx++)
        {
            for (int dz = -viewDistance; dz <= viewDistance; dz++)
            {
                if (dx * dx + dz * dz > viewDistance * viewDistance + viewDistance) continue;
                Vector2Int coord = center + new Vector2Int(dx, dz);
                if (!loaded.ContainsKey(coord)) needed.Add(coord);
            }
        }
        needed.Sort((a, b) => (a - center).sqrMagnitude.CompareTo((b - center).sqrMagnitude));
        foreach (Vector2Int coord in needed) pending.Enqueue(coord);
    }

    private void UnloadFar(Vector2Int center)
    {
        List<Vector2Int> remove = new List<Vector2Int>();
        foreach (KeyValuePair<Vector2Int, GameObject> pair in loaded)
        {
            Vector2Int d = pair.Key - center;
            if (Mathf.Max(Mathf.Abs(d.x), Mathf.Abs(d.y)) > viewDistance + 1) remove.Add(pair.Key);
        }
        foreach (Vector2Int coord in remove)
        {
            GameObject chunk = loaded[coord];
            chunk.SetActive(false);
            pool.Push(chunk);
            loaded.Remove(coord);
        }
    }

    private void CreateChunk(Vector2Int coord)
    {
        GameObject chunk;
        if (pool.Count > 0)
        {
            chunk = pool.Pop();
        }
        else
        {
            chunk = new GameObject("Chunk");
            chunk.transform.SetParent(transform, false);
            chunk.AddComponent<MeshFilter>().sharedMesh = new Mesh();
            chunk.AddComponent<MeshRenderer>().sharedMaterial = material;
            chunk.AddComponent<MeshCollider>();
        }
        chunk.name = "Chunk " + coord.x + "," + coord.y;
        chunk.transform.position = new Vector3(coord.x * ChunkWorldSize, 0f, coord.y * ChunkWorldSize);

        int row = chunkSize + 1;
        for (int z = 0; z < row; z++)
        {
            for (int x = 0; x < row; x++)
            {
                float wx = coord.x * ChunkWorldSize + x * cellSize;
                float wz = coord.y * ChunkWorldSize + z * cellSize;
                vertices[z * row + x] = new Vector3(x * cellSize, HeightAt(wx, wz), z * cellSize);
            }
        }
        Mesh mesh = chunk.GetComponent<MeshFilter>().sharedMesh;
        mesh.Clear();
        mesh.vertices = vertices;
        mesh.triangles = triangles;
        mesh.RecalculateNormals();
        mesh.RecalculateBounds();
        MeshCollider meshCollider = chunk.GetComponent<MeshCollider>();
        meshCollider.sharedMesh = null;
        meshCollider.sharedMesh = mesh;
        chunk.SetActive(true);
        loaded[coord] = chunk;
    }
}
```

Chunk coordinates are the player's position divided by the chunk's world size, and the work happens only when that integer pair changes. Because height is a pure function of world X/Z, any chunk can be rebuilt at any time and its border vertices always line up with its neighbour's. Loading is rate limited to `chunksPerFrame` and sorted nearest-first to avoid hitches, and unloaded chunks keep their object, mesh and collider in a pool for reuse.
